use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () > { let matches = Command :: new ("syn-mold") . version ("0.1.0") . about ("Extract syn usage signatures and generate compile-time checked replacements") . arg (Arg :: new ("input") . short ('i') . long ("input") . value_name ("FILE") . help ("Input Rust file with syn usage") . required (true)) . arg (Arg :: new ("output") . short ('o') . long ("output") . value_name ("FILE") . help ("Output file for molded code")) . arg (Arg :: new ("analysis") . short ('a') . long ("analysis") . help ("Show detailed static analysis") . action (clap :: ArgAction :: SetTrue)) . arg (Arg :: new ("replace") . short ('r') . long ("replace") . help ("Generate replacement code using mold wrappers") . action (clap :: ArgAction :: SetTrue)) . get_matches () ; let input_file = matches . get_one :: < String > ("input") . unwrap () ; let output_file = matches . get_one :: < String > ("output") ; let show_analysis = matches . get_flag ("analysis") ; let generate_replacement = matches . get_flag ("replace") ; println ! ("🔍 syn-mold: Analyzing syn usage in {}" , input_file) ; let input_content = fs :: read_to_string (input_file) ? ; let input_tokens : proc_macro2 :: TokenStream = syn :: parse_str (& input_content) ? ; let mut mold = SynMold :: new () ; let extraction = mold . extract_mold (input_tokens) ? ; if show_analysis { print_analysis (& extraction) ; } let output_code = if generate_replacement { extraction . generate_replacement () } else { extraction . mold_wrapper . clone () } ; if let Some (output_file) = output_file { fs :: write (output_file , output_code . to_string ()) ? ; println ! ("✅ Molded code written to {}" , output_file) ; } else { println ! ("📄 Generated mold wrapper:") ; println ! ("{}" , output_code) ; } generate_analysis_report (& extraction , input_file) ? ; Ok (()) }